pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        vm.assume(receiver != address(this));
        address owner = address(this);
        uint256 initialOwnerBalance = owner.balance;
        vm.deal(owner, 1e18);
        // fund contract so it can send
        (bool ok, ) = address(c).call{value: 1e18}("");
        require(ok);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));
        if (receiver == address(0)) {
            assertTrue(initialOwnerBalance == owner.balance, "Owner balance changed when sending to zero address");
        } else {
            assertTrue(success || initialOwnerBalance == owner.balance, "Owner balance changed unexpectedly");
        }
    }
}

