// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        vm.assume(amount > 0 && amount <= address(this).balance);

        // Fund the contract so that transfer can succeed
        vm.deal(address(c), amount);

        // For reference C: sendTo must revert if receiver is a contract that rejects Ether
        // We use a helper contract that rejects incoming Ether
        Rejector rejector = new Rejector();
        vm.prank(address(this));

        // The reference contract should revert when trying to send to Rejector
        vm.expectRevert();
        c.sendTo(address(rejector), amount);
        assertTrue(true);
    }
}

contract Rejector {
    receive() external payable {
        revert("reject");
    }
}
